// Some portions generated by Claude
'use strict';

// A query tab's result saved in the browser and shown again by a later page (ExecPlan
// .agent/execplan-query-tabs-g2.md, Part 2, M3): the controller persists a complete result and keeps its row store
// for the tab; a later page's controller restores it from the snapshot without a request, and Load more continues it.

const test = require('node:test');
const assert = require('node:assert/strict');
const { loadApi, response, batch } = require('./query-load-more-harness.js');
const { fakeIndexedDB, realWorkerFactory } = require('./row-store-worker-harness.js');

const REGISTRY = 'rdf4j.workbench.row-store.v2:';
const KEPT_FOR = { scope: '["sha256:abc","","owned"]', tabId: 't1' };

function mapStorage() {
    const values = new Map();
    return {
        values,
        get length() { return values.size; },
        key(index) { return [...values.keys()][index] || null; },
        getItem(key) { return values.has(key) ? values.get(key) : null; },
        setItem(key, value) { values.set(key, String(value)); },
        removeItem(key) { values.delete(key); }
    };
}

async function settle(rounds = 60) {
    for (let count = 0; count < rounds; count++) await new Promise(resolve => setImmediate(resolve));
}

/** One browser (IndexedDB and localStorage) whose pages each bind a Query form to a streamed result controller. */
function browser() {
    const storage = fakeIndexedDB();
    const localStorage = mapStorage();
    return {
        storage,
        localStorage,
        page(responses = []) {
            const loaded = loadApi({ localStorage });
            const { api, document } = loaded;
            const form = document.createElement('form');
            form.setAttribute('action', '/repositories/owned/query');
            for (const [name, value] of Object.entries({ query: 'SELECT ?value WHERE { VALUES ?value { 0 1 2 3 } }',
                queryLn: 'SPARQL', infer: 'true', 'query-timeout': '60', 'batch-size': '2' })) {
                const control = document.createElement('input');
                control.name = name;
                control.value = value;
                form.appendChild(control);
            }
            const target = document.createElement('section');
            target.id = 'query-results';
            document.body.appendChild(form);
            document.body.appendChild(target);
            const requests = [];
            const summaries = [];
            const ended = [];
            target.addEventListener('workbench:query-result-summary', (event) => summaries.push(event.detail));
            const pending = [...responses];
            const controller = api.bindMainQueryForm(form, target, {
                maxDomRows: 8,
                rowStoreOptions: { workerFactory: realWorkerFactory(storage).factory, storageTimeout: 2000 },
                onBatchEnd: (which) => ended.push(which),
                async fetcher(url, init) {
                    requests.push({ url, init });
                    return response(pending.shift());
                }
            });
            const lastSummary = () => summaries[summaries.length - 1];
            return Object.assign(loaded, { form, target, requests, summaries, ended, controller, lastSummary,
                respond: (records) => pending.push(records) });
        }
    };
}

function entryOf(localStorage, id) {
    const value = localStorage.getItem(REGISTRY + id);
    return value === null ? null : JSON.parse(value);
}

test('a complete result is saved for its tab and shown by a later page without a request; Load more continues it',
    async () => {
        const shared = browser();
        const first = shared.page([batch([0, 1], 0, true, { 'total-result-count': 4 })]);
        first.controller.submit();
        await settle();
        assert.equal(first.ended.length, 1, 'the page is told when a batch ends');
        assert.equal(first.ended[0], first.controller);
        const saved = await first.controller.saveResult(KEPT_FOR);
        assert.ok(saved, 'the result is saved');
        assert.match(saved.storeId, /^rows-/);
        assert.equal(saved.rows, 2);
        assert.equal(saved.view, 'tuple');
        assert.deepEqual(Array.from(saved.vars), ['value']);
        assert.equal(saved.batchSize, 2);
        assert.equal(saved.knownTotal, 4);
        assert.equal(new URLSearchParams(saved.request).get('query'),
            'SELECT ?value WHERE { VALUES ?value { 0 1 2 3 } }');
        assert.equal(saved.terminalMetadata['result-has-more'], true);
        const entry = entryOf(shared.localStorage, saved.storeId);
        assert.equal(entry.retained.tabId, 't1');
        assert.equal(entry.retained.rows, 2);
        assert.equal(entry.retained.owner, first.api.rowStoreDocumentOwner);
        first.controller.dispose();
        await settle();
        assert.ok(entryOf(shared.localStorage, saved.storeId), 'disposing the result keeps it in the browser');

        const later = shared.page([batch([2, 3], 2, false, { 'total-result-count': 4 })]);
        later.controller.restore(JSON.parse(JSON.stringify(saved)));
        await settle();
        assert.equal(later.requests.length, 0, 'a saved result is shown without asking the server');
        assert.equal(later.lastSummary().rowCount, 2);
        assert.equal(later.lastSummary().complete, true);
        const loadMore = later.target.querySelector('.query-result-load-more');
        assert.equal(loadMore.hidden, false, 'its Load more continues where it was left');
        assert.equal(later.controller.hasResult(), true);

        later.controller.loadMore();
        await settle();
        assert.equal(later.requests.length, 1);
        const body = later.requests[0].init.body;
        assert.equal(body.get('batch-offset'), '2');
        assert.equal(body.get('batch-known-total'), '4', 'the saved exact total goes with the continuation');
        assert.equal(body.get('query'), 'SELECT ?value WHERE { VALUES ?value { 0 1 2 3 } }');
        assert.equal(later.lastSummary().rowCount, 4);
        assert.equal(later.ended.length, 1);
        const again = await later.controller.saveResult(KEPT_FOR);
        assert.equal(again.storeId, saved.storeId, 'Load more grows the same saved store');
        assert.equal(again.rows, 4);
        assert.equal(entryOf(shared.localStorage, saved.storeId).retained.owner, later.api.rowStoreDocumentOwner);
        later.controller.dispose();
    });

test('a trimmed saved result shows the rows it kept and continues after them; a longer one is cut back', async () => {
    const shared = browser();
    const first = shared.page([batch([0, 1], 0, false)]);
    first.controller.submit();
    await settle();
    const saved = await first.controller.saveResult(KEPT_FOR);
    first.controller.dispose();
    await settle();

    // Trimmed to one row to make room (M4 does this through openRowStore and truncate).
    const trimmer = shared.page();
    const reference = { id: saved.storeId, count: saved.rows, bytes: 0, created: 0 };
    const store = await trimmer.api.openRowStore(reference, { workerFactory: realWorkerFactory(shared.storage).factory });
    await store.truncate(1);
    await store.release();

    const later = shared.page([batch([1], 1, false)]);
    later.controller.restore(saved);
    await settle();
    assert.equal(later.lastSummary().rowCount, 1);
    assert.match(later.target.textContent, /Saved the first 1 of 2 rows/);
    assert.equal(later.target.querySelector('.query-result-load-more').hidden, false,
        'Load more fetches the rows trimmed away');
    later.controller.loadMore();
    await settle();
    assert.equal(later.requests[0].init.body.get('batch-offset'), '1');
    assert.equal(later.lastSummary().rowCount, 2);
    later.controller.dispose();
    await settle();

    // A page that left during a Load more wrote rows the snapshot does not count.
    const grower = shared.page();
    const grown = await grower.api.openRowStore(reference, { workerFactory: realWorkerFactory(shared.storage).factory });
    await grown.append([[{ kind: 'literal', value: 'extra' }]]);
    assert.equal(await grown.count(), 3);
    await grown.release();
    const third = shared.page();
    third.controller.restore(saved);
    await settle();
    assert.equal(third.lastSummary().rowCount, 2, 'the rows the snapshot does not count are cut back');
    third.controller.dispose();
});

test('a saved result that is gone, or open in another window, says so instead of showing rows', async () => {
    const shared = browser();
    const first = shared.page([batch([0, 1], 0, false)]);
    first.controller.submit();
    await settle();
    const saved = await first.controller.saveResult(KEPT_FOR);
    first.controller.dispose();
    await settle();

    const holder = shared.page();
    holder.controller.restore(saved);
    await settle();
    assert.equal(holder.lastSummary().rowCount, 2);
    const other = shared.page();
    other.controller.restore(saved);
    // The other window waits a moment for the first to let the result go, as after a reload.
    await new Promise((resolve) => setTimeout(resolve, 1000));
    await settle();
    assert.equal(other.lastSummary().error, true);
    assert.match(other.target.textContent, /open in another window/);
    holder.controller.dispose();
    other.controller.dispose();
    await settle();

    shared.storage.databases.clear();
    const after = shared.page();
    after.controller.restore(saved);
    await settle();
    assert.match(after.target.textContent, /no longer stored in this browser/);
    assert.equal(entryOf(shared.localStorage, saved.storeId), null);
    after.controller.dispose();
});

test('an answer and an empty result are saved without a row store', async () => {
    const shared = browser();
    const first = shared.page([[{ type: 'head', version: 1 }, { type: 'view', id: 'boolean' },
        { type: 'boolean', value: true }, { type: 'end', metadata: { 'query-elapsed-ms': 3, 'query-result-status': 'completed' } }]]);
    first.controller.submit();
    await settle();
    const saved = await first.controller.saveResult(KEPT_FOR);
    assert.equal(saved.storeId, null);
    assert.equal(saved.view, 'boolean');
    assert.equal(saved.booleanValue, true);
    first.controller.dispose();
    const later = shared.page();
    later.controller.restore(saved);
    await settle();
    assert.equal(later.requests.length, 0);
    assert.match(later.target.textContent, /Answer/);
    later.controller.dispose();
});

test('a result that failed or is still running is not saved', async () => {
    const shared = browser();
    const first = shared.page([[{ type: 'head', version: 1 }, { type: 'view', id: 'error' },
        { type: 'error', status: 400, code: 'malformed-query', message: 'Bad query' }]]);
    first.controller.submit();
    await settle();
    assert.equal(await first.controller.saveResult(KEPT_FOR), null);
    first.controller.dispose();
});

test('when browser storage is full even after trimming, the result keeps the rows that fit and Load more the rest',
    async () => {
        const { MemoryWorker } = require('./query-load-more-harness.js');
        const refusing = { on: false };
        class FullWorker extends MemoryWorker {
            postMessage(message) {
                if (message.op === 'append' && refusing.on) {
                    queueMicrotask(() => {
                        const answer = { requestId: message.requestId, ok: false, error: 'QuotaExceededError: full',
                            errorName: 'QuotaExceededError' };
                        for (const callback of this.listeners.get('message') || []) callback({ data: answer });
                    });
                    return;
                }
                super.postMessage(message);
            }
        }
        const loaded = loadApi({ localStorage: mapStorage() });
        const { api, document } = loaded;
        const form = document.createElement('form');
        form.setAttribute('action', '/repositories/owned/query');
        for (const [name, value] of Object.entries({ query: 'SELECT ?value {}', 'batch-size': '2' })) {
            const control = document.createElement('input');
            control.name = name;
            control.value = value;
            form.appendChild(control);
        }
        const target = document.createElement('section');
        document.body.appendChild(form);
        document.body.appendChild(target);
        const responses = [batch([0, 1], 0, true, { 'total-result-count': 4 }),
            batch([2, 3], 2, false, { 'total-result-count': 4 })];
        const controller = api.bindMainQueryForm(form, target, {
            rowStoreOptions: { workerFactory: () => new FullWorker(), spillRowLimit: 0 },
            async fetcher() { return response(responses.shift()); }
        });
        controller.submit();
        await settle();
        refusing.on = true;
        controller.loadMore();
        await settle(200);
        const saved = await controller.saveResult(KEPT_FOR);
        assert.ok(saved, 'what fits is saved');
        assert.equal(saved.rows, 2);
        assert.equal(saved.terminalMetadata['result-has-more'], true);
        assert.equal(saved.terminalMetadata['result-next-offset'], 2);
        assert.match(target.textContent, /Browser storage is full: 2 rows are kept/);
        assert.equal(target.querySelector('.query-result-load-more').hidden, false);
        controller.dispose();
    });

test('a result whose query ran more than 15 minutes ago says how long ago, the exact time in its tooltip', async () => {
    const shared = browser();
    const first = shared.page([batch([0, 1], 0, false, { 'query-elapsed-ms': 109, 'query-result-status': 'completed',
        'total-result-count': 2 })]);
    first.controller.submit();
    await settle();
    assert.ok(!/ran .* ago/.test(first.target.textContent), 'a fresh result gives no age');
    const saved = await first.controller.saveResult(KEPT_FOR);
    assert.ok(Math.abs(saved.ranAt - Date.now()) < 5000, 'the snapshot keeps when the query ran');
    first.controller.dispose();

    const later = shared.page();
    later.controller.restore(Object.assign({}, saved, { ranAt: Date.now() - 2 * 60 * 60 * 1000 - 1000 }));
    await settle();
    assert.match(later.target.textContent, /2 rows · complete in 109 ms · ran 2 h ago/);
    const shownStatus = [...later.target.querySelectorAll('[title]')].filter(element => /^Ran /.test(element.getAttribute('title')));
    assert.equal(shownStatus.length, 1, 'the exact time is in the tooltip');
    later.controller.dispose();
});

test('the age reads in minutes, hours and days', () => {
    const { api } = loadApi();
    const now = Date.UTC(2026, 10, 8, 12);
    assert.equal(api.ranAgo(now - 14 * 60000, now), '');
    assert.equal(api.ranAgo(now - 16 * 60000, now), 'ran 16 min ago');
    assert.equal(api.ranAgo(now - 90 * 60000, now), 'ran 1 h ago');
    assert.equal(api.ranAgo(now - 25 * 3600000, now), 'ran 1 day ago');
    assert.equal(api.ranAgo(now - 72 * 3600000, now), 'ran 3 days ago');
    assert.equal(api.ranAgo(0, now), '');
});
